def evaluate(expr: str, env: dict[str, float] | None = None) -> int | float:
    if env is None:
        env = {}

    # Tokenize
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        ch = expr[i]
        if ch.isspace():
            i += 1
            continue
        # Numbers: integer or decimal (including .5, 2.)
        if ch.isdigit() or (ch == '.' and i + 1 < n and expr[i+1].isdigit()):
            j = i
            is_float = False
            while j < n and expr[j].isdigit():
                j += 1
            if j < n and expr[j] == '.':
                is_float = True
                j += 1
                while j < n and expr[j].isdigit():
                    j += 1
            if is_float:
                tokens.append(('NUMBER', float(expr[i:j])))
            else:
                tokens.append(('NUMBER', int(expr[i:j])))
            i = j
            continue
        # Identifiers
        if ch.isalpha() or ch == '_':
            j = i
            while j < n and (expr[j].isalnum() or expr[j] == '_'):
                j += 1
            tokens.append(('IDENT', expr[i:j]))
            i = j
            continue
        # Two-char operators
        if i + 1 < n:
            two = expr[i:i+2]
            if two in ('||', '&&', '==', '!=', '<=', '>='):
                tokens.append(('OP', two))
                i += 2
                continue
        # Single-char operators and punctuation
        if ch in '+-*/%^!<>?:()':
            tokens.append(('OP', ch))
            i += 1
            continue
        raise SyntaxError(f"Unexpected character: {ch}")

    if not tokens:
        raise SyntaxError("Empty expression")

    pos = 0

    def peek():
        nonlocal pos
        if pos < len(tokens):
            return tokens[pos]
        return (None, None)

    def next_token():
        nonlocal pos
        if pos >= len(tokens):
            raise SyntaxError("Unexpected end of expression")
        tok = tokens[pos]
        pos += 1
        return tok

    def parse_ternary():
        # a ? b : c, right-associative
        left = parse_or()
        if peek()[0] == 'OP' and peek()[1] == '?':
            next_token()  # consume '?'
            middle = parse_ternary()  # right-associative
            if not (peek()[0] == 'OP' and peek()[1] == ':'):
                raise SyntaxError("Expected ':' in ternary expression")
            next_token()  # consume ':'
            right = parse_ternary()
            if left != 0:
                return middle
            else:
                return right
        return left

    def parse_or():
        left = parse_and()
        while peek()[0] == 'OP' and peek()[1] == '||':
            next_token()
            right = parse_and()
            if left != 0:
                left = 1
            else:
                left = right
        return left

    def parse_and():
        left = parse_comparison()
        while peek()[0] == 'OP' and peek()[1] == '&&':
            next_token()
            right = parse_comparison()
            if left != 0:
                left = right
            else:
                left = 0
        return left

    def parse_comparison():
        left = parse_additive()
        if peek()[0] == 'OP' and peek()[1] in ('==', '!=', '<', '<=', '>', '>='):
            op = next_token()[1]
            right = parse_additive()
            # Non-associative: no chaining allowed
            result = 0
            if op == '==':
                result = 1 if left == right else 0
            elif op == '!=':
                result = 1 if left != right else 0
            elif op == '<':
                result = 1 if left < right else 0
            elif op == '<=':
                result = 1 if left <= right else 0
            elif op == '>':
                result = 1 if left > right else 0
            elif op == '>=':
                result = 1 if left >= right else 0
            # Check for another comparison operator (chaining is an error)
            if peek()[0] == 'OP' and peek()[1] in ('==', '!=', '<', '<=', '>', '>='):
                raise SyntaxError("Comparison operators cannot be chained")
            return result
        return left

    def parse_additive():
        left = parse_multiplicative()
        while peek()[0] == 'OP' and peek()[1] in ('+', '-'):
            op = next_token()[1]
            right = parse_multiplicative()
            if op == '+':
                left = left + right
            else:
                left = left - right
        return left

    def parse_multiplicative():
        left = parse_power()
        while peek()[0] == 'OP' and peek()[1] in ('*', '/', '%'):
            op = next_token()[1]
            right = parse_power()
            if op == '*':
                left = left * right
            elif op == '/':
                if right == 0:
                    raise ZeroDivisionError("division by zero")
                if isinstance(left, int) and isinstance(right, int):
                    if left % right == 0:
                        left = left // right
                    else:
                        left = left / right
                else:
                    left = left / right
            elif op == '%':
                if right == 0:
                    raise ZeroDivisionError("modulo by zero")
                left = left % right
        return left

    def parse_power():
        # ^ is right-associative, binds tighter than unary minus on its left
        base = parse_atom()
        if peek()[0] == 'OP' and peek()[1] == '^':
            next_token()  # consume ^
            exponent = parse_unary()  # right-associative, can include unary
            return base ** exponent
        return base

    def parse_unary():
        if peek()[0] == 'OP' and peek()[1] in ('-', '+', '!'):
            op = next_token()[1]
            operand = parse_unary()  # right-associative for unary
            if op == '-':
                return -operand
            elif op == '+':
                return +operand
            elif op == '!':
                return 1 if operand == 0 else 0
        return parse_power()

    def parse_atom():
        tok = peek()
        if tok[0] == 'NUMBER':
            next_token()
            return tok[1]
        elif tok[0] == 'IDENT':
            name = tok[1]
            next_token()
            # Check for function call
            if peek()[0] == 'OP' and peek()[1] == '(':
                next_token()  # consume '('
                args = []
                if not (peek()[0] == 'OP' and peek()[1] == ')'):
                    while True:
                        args.append(parse_ternary())
                        if peek()[0] == 'OP' and peek()[1] == ',':
                            next_token()  # consume ','
                        else:
                            break
                if not (peek()[0] == 'OP' and peek()[1] == ')'):
                    raise SyntaxError("Expected ')' after function arguments")
                next_token()  # consume ')'

                if name == 'abs':
                    if len(args) != 1:
                        raise SyntaxError("abs takes exactly 1 argument")
                    return abs(args[0])
                elif name == 'min':
                    if len(args) < 1:
                        raise SyntaxError("min takes at least 1 argument")
                    result = args[0]
                    for a in args[1:]:
                        if a < result:
                            result = a
                    return result
                elif name == 'max':
                    if len(args) < 1:
                        raise SyntaxError("max takes at least 1 argument")
                    result = args[0]
                    for a in args[1:]:
                        if a > result:
                            result = a
                    return result
                else:
                    raise NameError(f"Unknown function: {name}")
            else:
                # Variable lookup
                if name not in env:
                    raise NameError(f"Unknown variable: {name}")
                return env[name]
        elif tok[0] == 'OP' and tok[1] == '(':
            next_token()  # consume '('
            val = parse_ternary()
            if not (peek()[0] == 'OP' and peek()[1] == ')'):
                raise SyntaxError("Expected ')'")
            next_token()  # consume ')'
            return val
        else:
            raise SyntaxError(f"Unexpected token: {tok}")

    result = parse_ternary()

    if pos != len(tokens):
        raise SyntaxError(f"Trailing tokens after expression")

    return result
