        raise ValueError("Empty grid")

    n = len(grid)
    m = len(grid[0]) if n > 0 else 0

    # Check ragged rows
    for i in range(n):
        if len(grid[i]) != m:
            raise ValueError("Ragged rows")

    # Find S and E, count letters, check unknown chars
    start = None
    end = None
    letter_count = defaultdict(int)
    pad_positions = defaultdict(list)  # letter -> list of (row, col)

    valid_chars = set("SE#.") | set(string.digits[1:10]) | set(string.ascii_lowercase)

    for r in range(n):
        for c in range(m):
            ch = grid[r][c]
            if ch not in valid_chars:
                raise ValueError(f"Unknown character '{ch}'")
            if ch == 'S':
                if start is not None:
                    raise ValueError("More than one S")
                start = (r, c)
            elif ch == 'E':
                if end is not None:
                    raise ValueError("More than one E")
                end = (r, c)
            elif ch in string.ascii_lowercase:
                letter_count[ch] += 1
                pad_positions[ch].append((r, c))

    if start is None:
        raise ValueError("No S found")
    if end is None:
        raise ValueError("No E found")

    for ch, count in letter_count.items():
        if count == 1 or count > 2:
            raise ValueError(f"Letter '{ch}' appears {count} times")

    # Get cost of a cell
    def cell_cost(r, c):
        ch = grid[r][c]
        if ch in 'SE':
            return 1
        elif ch == '.':
            return 1
        elif ch == '#':
            return -1  # wall
        elif ch in string.digits[1:10]:
            return int(ch)
        else:  # lowercase letter
            return 1

    def get_teleport_target(r, c):
        ch = grid[r][c]
        if ch in string.ascii_lowercase:
            positions = pad_positions[ch]
            if len(positions) == 2:
                other = [p for p in positions if p != (r, c)]
                if other:
                    return other[0]
        return None

    # Priority queue: (cost, path_string, r, c)
    # We want to minimize cost first, then lex smallest path string.
    # Python heap compares tuples lexicographically, so (cost, path, r, c) works.

    if start == end:
        return (0, "")

    heap = [(0, "", start[0], start[1])]

    while heap:
        cost, path, r, c = heapq.heappop(heap)

        if (r, c) == end:
            return (cost, path)

        # Try all moves in lex order: D, L, R, T, U

        # D
        nr, nc = r + 1, c
        if 0 <= nr < n and 0 <= nc < m:
            ch = grid[nr][nc]
            if ch != '#':
                c_cost = cell_cost(nr, nc)
                new_cost = cost + c_cost
                heapq.heappush(heap, (new_cost, path + "D", nr, nc))

        # L
        nr, nc = r, c - 1
        if 0 <= nr < n and 0 <= nc < m:
            ch = grid[nr][nc]
            if ch != '#':
                c_cost = cell_cost(nr, nc)
                new_cost = cost + c_cost
                heapq.heappush(heap, (new_cost, path + "L", nr, nc))

        # R
        nr, nc = r, c + 1
        if 0 <= nr < n and 0 <= nc < m:
            ch = grid[nr][nc]
            if ch != '#':
                c_cost = cell_cost(nr, nc)
                new_cost = cost + c_cost
                heapq.heappush(heap, (new_cost, path + "R", nr, nc))

        # T - teleport
        target = get_teleport_target(r, c)
        if target is not None:
            tr, tc = target
            c_cost = 2  # cost of teleport move is 2
            new_cost = cost + c_cost
            heapq.heappush(heap, (new_cost, path + "T", tr, tc))

        # U
        nr, nc = r - 1, c
        if 0 <= nr < n and 0 <= nc < m:
            ch = grid[nr][nc]
            if ch != '#':
                c_cost = cell_cost(nr, nc)
                new_cost = cost + c_cost
                heapq.heappush(heap, (new_cost, path + "U", nr, nc))

    return None
