def load_ini(text: str) -> dict[str, dict[str, str]]:
    lines = text.split('\n')
    raw_sections: dict[str, dict[str, str]] = {}
    current_section = ""

    # last_entry_info: (section, key, [value_parts]) for continuation handling
    last_entry_info = None

    i = 0
    n = len(lines)

    while i < n:
        line_num = i + 1
        raw_line = lines[i]

        # Check for continuation: non-empty line starting with whitespace AND follows an entry
        if (last_entry_info is not None and 
            len(raw_line) > 0 and 
            raw_line[0] in (' ', '\t') and 
            raw_line.strip() != ""):
            section, key, value_parts = last_entry_info
            value_parts.append(raw_line.strip())
            i += 1
            continue

        # Blank line or comment-only line
        stripped = raw_line.strip()

        if stripped == "":
            last_entry_info = None
            i += 1
            continue

        if stripped.startswith('#') or stripped.startswith(';'):
            last_entry_info = None
            i += 1
            continue

        # Check for section header
        if stripped.startswith('['):
            if not stripped.endswith(']'):
                raise ValueError(f"line {line_num}: unclosed section header")
            section_name = stripped[1:-1].strip()
            current_section = section_name
            if section_name not in raw_sections:
                raw_sections[section_name] = {}
            last_entry_info = None
            i += 1
            continue

        # Must be an entry: key = value or key: value
        # Find first '=' or ':' that is not inside double quotes
        sep_idx = -1
        in_quotes = False
        j = 0
        while j < len(raw_line):
            c = raw_line[j]
            if in_quotes:
                if c == '\\' and j + 1 < len(raw_line):
                    j += 2
                    continue
                elif c == '"':
                    in_quotes = False
            else:
                if c == '"':
                    in_quotes = True
                elif c == '=' or c == ':':
                    sep_idx = j
                    break
            j += 1

        if sep_idx == -1:
            raise ValueError(f"line {line_num}: missing separator")

        key_raw = raw_line[:sep_idx].strip().lower()
        value_raw = raw_line[sep_idx + 1:]

        # Process inline comments in value_raw
        # Inline comment: ' ;' or ' #' (whitespace before marker) ends the value, unless inside double quotes.
        val_str = value_raw
        in_quotes = False
        k = 0
        comment_start = -1
        while k < len(val_str):
            c = val_str[k]
            if in_quotes:
                if c == '\\' and k + 1 < len(val_str):
                    k += 2
                    continue
                elif c == '"':
                    in_quotes = False
            else:
                if c == '"':
                    in_quotes = True
                elif k + 1 < len(val_str) and val_str[k] == ' ' and (val_str[k+1] == ';' or val_str[k+1] == '#'):
                    comment_start = k
                    break
            k += 1

        if comment_start != -1:
            val_str = val_str[:comment_start]

        # Now handle the value
        val_stripped = val_str.strip()

        if val_stripped.startswith('"'):
            # Must be fully wrapped in double quotes
            if not val_stripped.endswith('"') or len(val_stripped) < 2:
                raise ValueError(f"line {line_num}: unterminated quote")
            inner = val_stripped[1:-1]
            # Handle escaped quotes: \" becomes "
            result_chars = []
            m = 0
            while m < len(inner):
                if inner[m] == '\\' and m + 1 < len(inner) and inner[m+1] == '"':
                    result_chars.append('"')
                    m += 2
                else:
                    result_chars.append(inner[m])
                    m += 1
            value = ''.join(result_chars)
        else:
            value = val_stripped

        # Store the entry
        section = current_section
        if section not in raw_sections:
            raw_sections[section] = {}

        raw_sections[section][key_raw] = value

        # Set last_entry_info for potential continuation
        last_entry_info = (section, key_raw, [value])

        i += 1

    # Now resolve interpolation
    def resolve_value(section: str, key: str, visited: set) -> str:
        if (section, key) in visited:
            raise ValueError(f"cycle detected for {section}:{key}")

        if section not in raw_sections or key not in raw_sections[section]:
            raise ValueError(f"undefined reference {section}:{key}")

        val = raw_sections[section][key]

        # Parse the value for interpolation references
        result = []
        idx = 0
        while idx < len(val):
            if val[idx] == '$':
                if idx + 1 >= len(val):
                    result.append('$')
                    idx += 1
                    continue

                if val[idx+1] == '$':
                    # Literal $
                    result.append('$')
                    idx += 2
                    continue

                if val[idx+1] == '{':
                    # Find closing }
                    close_idx = val.find('}', idx + 2)
                    if close_idx == -1:
                        raise ValueError(f"unterminated interpolation in {section}:{key}")

                    ref_str = val[idx+2:close_idx]

                    if ':' in ref_str:
                        ref_section, ref_key = ref_str.split(':', 1)
                    else:
                        ref_section = section
                        ref_key = ref_str

                    new_visited = visited | {(section, key)}
                    resolved = resolve_value(ref_section, ref_key, new_visited)
                    result.append(resolved)
                    idx = close_idx + 1
                else:
                    # Not a valid interpolation start, just append $
                    result.append('$')
                    idx += 1
            else:
                result.append(val[idx])
                idx += 1

        return ''.join(result)

    # Resolve all values
    resolved_sections: dict[str, dict[str, str]] = {}
    for section in raw_sections:
        resolved_sections[section] = {}
        for key in raw_sections[section]:
            try:
                resolved_val = resolve_value(section, key, set())
                resolved_sections[section][key] = resolved_val
            except ValueError as e:
                raise e

    # Only include section "" if it has keys
    if "" in resolved_sections and len(resolved_sections[""]) == 0:
        del resolved_sections[""]

    return resolved_sections
