import re
from typing import List, Optional, Tuple

class Version:
    __slots__ = ('major', 'minor', 'patch', 'prerelease', 'build')

    def __init__(self, major: int, minor: int, patch: int, prerelease=None, build=None):
        self.major = major
        self.minor = minor
        self.patch = patch
        # prerelease is a tuple of identifiers (strings), or None if no prerelease
        self.prerelease = tuple(prerelease) if prerelease else None
        self.build = tuple(build) if build else None

    def _precedence_key(self):
        # Build metadata ignored for ordering.
        # Prerelease: None means release (higher than any prerelease).
        # If prerelease exists, compare identifier by identifier.
        # We return a key that can be compared.
        # Strategy: 
        #   (major, minor, patch, has_prerelease_flag, prerelease_tuple)
        # But we need special handling for identifier comparison.
        # Let's implement __lt__, __gt__, etc. directly for clarity and correctness per spec.
        pass

    def _compare_prerelease(self, other: 'Version') -> int:
        """Compare self.prerelease vs other.prerelease. Returns -1, 0, 1."""
        # Both None: equal
        if self.prerelease is None and other.prerelease is None:
            return 0
        # self has prerelease, other doesn't: self < other (prerelease < release)
        if self.prerelease is not None and other.prerelease is None:
            return -1
        # self doesn't, other does: self > other
        if self.prerelease is None and other.prerelease is not None:
            return 1

        # Both have prereleases
        sp = self.prerelease
        op = other.prerelease

        for i in range(max(len(sp), len(op))):
            if i < len(sp) and i >= len(op):
                # self is longer, so self > other (a shorter prefix list is smaller)
                return 1
            if i >= len(sp) and i < len(op):
                # other is longer, so self < other
                return -1

            sid = sp[i]
            oid = op[i]

            # Check if both are numeric
            s_num = re.fullmatch(r'\d+', sid)
            o_num = re.fullmatch(r'\d+', oid)

            if s_num and o_num:
                sv = int(sid)
                ov = int(oid)
                if sv < ov: return -1
                if sv > ov: return 1
            elif s_num and not o_num:
                # numeric < alphanumeric
                return -1
            elif not s_num and o_num:
                # alphanumeric > numeric
                return 1
            else:
                # both alphanumeric, compare ASCII
                if sid < oid: return -1
                if sid > oid: return 1

        return 0

    def __eq__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        if self.major != other.major or self.minor != other.minor or self.patch != other.patch:
            return False
        # Build metadata ignored for equality? 
        # Spec says "build metadata ignored" in precedence. 
        # "== must follow precedence too". So build is ignored.
        if self.prerelease is None and other.prerelease is None:
            return True
        if self.prerelease is not None and other.prerelease is not None:
            return self.prerelease == other.prerelease
        return False

    def __lt__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        if self.major != other.major:
            return self.major < other.major
        if self.minor != other.minor:
            return self.minor < other.minor
        if self.patch != other.patch:
            return self.patch < other.patch

        # Compare prerelease
        cmp = self._compare_prerelease(other)
        return cmp < 0

    def __gt__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        if self.major != other.major:
            return self.major > other.major
        if self.minor != other.minor:
            return self.minor > other.minor
        if self.patch != other.patch:
            return self.patch > other.patch

        cmp = self._compare_prerelease(other)
        return cmp > 0

    def __le__(self, other):
        return self == other or self < other

    def __ge__(self, other):
        return self == other or self > other

    def __hash__(self):
        # Build ignored in hash? Usually yes if ignored in eq.
        return hash((self.major, self.minor, self.patch, self.prerelease))


def parse(v: str) -> Version:
    v = v.strip()
    if not v:
        raise ValueError("Empty version string")

    # Allow leading 'v' or '='
    if v[0] in ('v', '='):
        v = v[1:]

    # SemVer regex
    # MAJOR.MINOR.PATCH[-PRERELEASE][+BUILD]
    # No leading zeros in numeric parts.

    # Prerelease identifiers: [0-9A-Za-z-]+, non-empty. 
    # Numeric identifiers must not have leading zeros (unless "0" itself).
    # Alphanumeric identifiers can contain digits but cannot be all digits with leading zero? 
    # Spec: "no leading zeros in numeric parts or numeric prerelease identifiers".
    # This implies if an identifier is numeric, it must not have leading zeros.

    # Let's break down the string manually to handle validation properly.

    # Split off build metadata
    build = None
    if '+' in v:
        main_part, build_str = v.split('+', 1)
        if not build_str:
            raise ValueError("Empty build metadata")
        # Build identifiers: [0-9A-Za-z-]+
        build_ids = build_str.split('.')
        for bid in build_ids:
            if not re.fullmatch(r'[0-9A-Za-z-]+', bid):
                raise ValueError(f"Invalid build identifier: {bid}")
        build = tuple(build_ids)
        v = main_part
    else:
        main_part = v

    # Split off prerelease
    prerelease = None
    if '-' in main_part:
        core, pre_str = main_part.split('-', 1)
        if not pre_str:
            raise ValueError("Empty prerelease")
        pre_ids = pre_str.split('.')
        for pid in pre_ids:
            if not re.fullmatch(r'[0-9A-Za-z-]+', pid):
                raise ValueError(f"Invalid prerelease identifier: {pid}")
            # Check leading zeros for numeric identifiers
            if re.fullmatch(r'\d+', pid):
                if len(pid) > 1 and pid[0] == '0':
                    raise ValueError(f"Leading zero in numeric prerelease identifier: {pid}")
        prerelease = tuple(pre_ids)
        main_part = core
    else:
        core = main_part

    # Parse MAJOR.MINOR.PATCH
    parts = core.split('.')
    if len(parts) != 3:
        raise ValueError(f"Invalid version format: {core}")

    major_str, minor_str, patch_str = parts

    for p in (major_str, minor_str, patch_str):
        if not re.fullmatch(r'\d+', p):
            raise ValueError(f"Non-numeric part: {p}")
        # No leading zeros
        if len(p) > 1 and p[0] == '0':
            raise ValueError(f"Leading zero in numeric part: {p}")

    major = int(major_str)
    minor = int(minor_str)
    patch = int(patch_str)

    return Version(major, minor, patch, prerelease, build)


def _parse_partial_version(s: str) -> Tuple[Optional[int], Optional[int], Optional[int], Optional[tuple]]:
    """
    Parses a possibly partial version string.
    Returns (major, minor, patch, prerelease_tuple_or_None)
    Where None means "any" for that component in X-range context.
    But we also need to handle operators which change semantics.

