    """
    s = s.strip()
    if not s:
        raise ValueError("Empty partial version")

    if s[0] in ('v', '='):
        s = s[1:]

    # Check for X or x
    # X can be used for major, minor, patch.
    # e.g., 1.x, 1.2.*, X

    # Split by '.'
    parts = s.split('.')

    # Validate each part
    major = None
    minor = None
    patch = None
    prerelease = None

    # We need to handle cases like "1", "1.2", "1.2.3", "1.x", "1.2.*", "X"

    # Let's parse sequentially
    if len(parts) == 1:
        p = parts[0]
        if p in ('x', 'X', '*'):
            major = None
        else:
            if not re.fullmatch(r'\d+', p):
                raise ValueError(f"Invalid major version: {p}")
            if len(p) > 1 and p[0] == '0':
                raise ValueError(f"Leading zero in major: {p}")
            major = int(p)
    elif len(parts) == 2:
        p0, p1 = parts
        # Major
        if p0 in ('x', 'X', '*'):
            major = None
        else:
            if not re.fullmatch(r'\d+', p0):
                raise ValueError(f"Invalid major version: {p0}")
            if len(p0) > 1 and p0[0] == '0':
                raise ValueError(f"Leading zero in major: {p0}")
            major = int(p0)

        # Minor
        if p1 in ('x', 'X', '*'):
            minor = None
        else:
            if not re.fullmatch(r'\d+', p1):
                raise ValueError(f"Invalid minor version: {p1}")
            if len(p1) > 1 and p1[0] == '0':
                raise ValueError(f"Leading zero in minor: {p1}")
            minor = int(p1)
    elif len(parts) == 3:
        p0, p1, p2 = parts
        # Major
        if p0 in ('x', 'X', '*'):
            major = None
        else:
            if not re.fullmatch(r'\d+', p0):
                raise ValueError(f"Invalid major version: {p0}")
            if len(p0) > 1 and p0[0] == '0':
                raise ValueError(f"Leading zero in major: {p0}")
            major = int(p0)

        # Minor
        if p1 in ('x', 'X', '*'):
            minor = None
        else:
            if not re.fullmatch(r'\d+', p1):
                raise ValueError(f"Invalid minor version: {p1}")
            if len(p1) > 1 and p1[0] == '0':
                raise ValueError(f"Leading zero in minor: {p1}")
            minor = int(p1)

        # Patch
        if p2 in ('x', 'X', '*'):
            patch = None
        else:
            if not re.fullmatch(r'\d+', p2):
                raise ValueError(f"Invalid patch version: {p2}")
            if len(p2) > 1 and p2[0] == '0':
                raise ValueError(f"Leading zero in patch: {p2}")
            patch = int(p2)
    else:
        # More than 3 parts? Could be prerelease attached to the last part.
        # e.g., "1.2.3-alpha"
        # Let's re-parse by looking for '-' or '+' in the string first.

        # Actually, partial versions can have prereleases? 
        # Spec says: "Comparators: ... followed by a (possibly partial) version."
        # And "Prereleases: a version with a prerelease only satisfies..."
        # It implies comparators can have full versions with prereleases.

        # Let's handle the general case by splitting on '-' and '+' first.

        pass

    # The above simple split fails for "1.2.3-alpha".
    # Let's redo parsing more robustly.

    return _parse_partial_version_robust(s)


def _parse_partial_version_robust(s: str):
    """
    Returns (major, minor, patch, prerelease_tuple_or_None)
    None for major/minor/patch means X-range.
    """
    s = s.strip()
    if not s:
        raise ValueError("Empty partial version")

    if s[0] in ('v', '='):
        s = s[1:]

    # Split off build (ignored for range matching usually, but valid syntax)
    build = None
    main_part = s
    if '+' in s:
        main_part, build_str = s.split('+', 1)
        # Validate build identifiers
        if build_str:
            b_ids = build_str.split('.')
            for bid in b_ids:
                if not re.fullmatch(r'[0-9A-Za-z-]+', bid):
                    raise ValueError(f"Invalid build identifier: {bid}")

    # Split off prerelease
    prerelease = None
    core = main_part
    if '-' in main_part:
        core, pre_str = main_part.split('-', 1)
        if not pre_str:
            raise ValueError("Empty prerelease")
        pre_ids = pre_str.split('.')
        for pid in pre_ids:
            if not re.fullmatch(r'[0-9A-Za-z-]+', pid):
                raise ValueError(f"Invalid prerelease identifier: {pid}")
            if re.fullmatch(r'\d+', pid) and len(pid) > 1 and pid[0] == '0':
                raise ValueError(f"Leading zero in numeric prerelease identifier: {pid}")
        prerelease = tuple(pre_ids)

    # Parse core MAJOR.MINOR.PATCH (possibly partial)
    parts = core.split('.')

    major = None
    minor = None
    patch = None

    if len(parts) == 1:
        p = parts[0]
        if p in ('x', 'X', '*'):
            major = None
        else:
            if not re.fullmatch(r'\d+', p):
                raise ValueError(f"Invalid version part: {p}")
            if len(p) > 1 and p[0] == '0':
                raise ValueError(f"Leading zero in version part: {p}")
            major = int(p)
    elif len(parts) == 2:
        p0, p1 = parts
        if p0 in ('x', 'X', '*'):
            major = None
        else:
            if not re.fullmatch(r'\d+', p0):
                raise ValueError(f"Invalid version part: {p0}")
            if len(p0) > 1 and p0[0] == '0':
                raise ValueError(f"Leading zero in version part: {p0}")
            major = int(p0)

        if p1 in ('x', 'X', '*'):
            minor = None
        else:
            if not re.fullmatch(r'\d+', p1):
                raise ValueError(f"Invalid version part: {p1}")
            if len(p1) > 1 and p1[0] == '0':
                raise ValueError(f"Leading zero in version part: {p1}")
            minor = int(p1)
    elif len(parts) == 3:
        p0, p1, p2 = parts
        if p0 in ('x', 'X', '*'):
            major = None
        else:
            if not re.fullmatch(r'\d+', p0):
                raise ValueError(f"Invalid version part: {p0}")
            if len(p0) > 1 and p0[0] == '0':
                raise ValueError(f"Leading zero in version part: {p0}")
            major = int(p0)

        if p1 in ('x', 'X', '*'):
            minor = None
        else:
            if not re.fullmatch(r'\d+', p1):
                raise ValueError(f"Invalid version part: {p1}")
            if len(p1) > 1 and p1[0] == '0':
                raise ValueError(f"Leading zero in version part: {p1}")
            minor = int(p1)

        if p2 in ('x', 'X', '*'):
            patch = None
        else:
            if not re.fullmatch(r'\d+', p2):
                raise ValueError(f"Invalid version part: {p2}")
            if len(p2) > 1 and p2[0] == '0':
                raise ValueError(f"Leading zero in version part: {p2}")
            patch = int(p2)
    else:
        raise ValueError(f"Invalid partial version format: {core}")

    return major, minor, patch, prerelease


class Comparator:
    def __init__(self, op: str, major: Optional[int], minor: Optional[int], patch: Optional[int], prerelease: Optional[tuple]):
        self.op = op
        self.major = major
        self.minor = minor
        self.patch = patch
        self.prerelease = prerelease

    def matches(self, v: Version) -> bool:
