    if len(parts) != 3:
        raise ValueError(f"Invalid version format: {core}")

    major_str, minor_str, patch_str = parts

    for p in (major_str, minor_str, patch_str):
        if not re.fullmatch(r'\d+', p):
            raise ValueError(f"Non-numeric part: {p}")
        if len(p) > 1 and p[0] == '0':
            raise ValueError(f"Leading zero in numeric part: {p}")

    major = int(major_str)
    minor = int(minor_str)
    patch = int(patch_str)

    return Version(major, minor, patch, prerelease, build)


def _parse_partial_version_robust(s: str):
    """
    Returns (major, minor, patch, prerelease_tuple_or_None)
    None for major/minor/patch means X-range.
    """
    s = s.strip()
    if not s:
        raise ValueError("Empty partial version")

    if s[0] in ('v', '='):
        s = s[1:]

    build = None
    main_part = s
    if '+' in s:
        main_part, build_str = s.split('+', 1)
        if build_str:
            b_ids = build_str.split('.')
            for bid in b_ids:
                if not re.fullmatch(r'[0-9A-Za-z-]+', bid):
                    raise ValueError(f"Invalid build identifier: {bid}")

    prerelease = None
    core = main_part
    if '-' in main_part:
        core, pre_str = main_part.split('-', 1)
        if not pre_str:
            raise ValueError("Empty prerelease")
        pre_ids = pre_str.split('.')
        for pid in pre_ids:
            if not re.fullmatch(r'[0-9A-Za-z-]+', pid):
                raise ValueError(f"Invalid prerelease identifier: {pid}")
            if re.fullmatch(r'\d+', pid) and len(pid) > 1 and pid[0] == '0':
                raise ValueError(f"Leading zero in numeric prerelease identifier: {pid}")
        prerelease = tuple(pre_ids)

    parts = core.split('.')

    major = None
    minor = None
    patch = None

    if len(parts) == 1:
        p = parts[0]
        if p in ('x', 'X', '*'):
            major = None
        else:
            if not re.fullmatch(r'\d+', p):
                raise ValueError(f"Invalid version part: {p}")
            if len(p) > 1 and p[0] == '0':
                raise ValueError(f"Leading zero in version part: {p}")
            major = int(p)
    elif len(parts) == 2:
        p0, p1 = parts
        if p0 in ('x', 'X', '*'):
            major = None
        else:
            if not re.fullmatch(r'\d+', p0):
                raise ValueError(f"Invalid version part: {p0}")
            if len(p0) > 1 and p0[0] == '0':
                raise ValueError(f"Leading zero in version part: {p0}")
            major = int(p0)

        if p1 in ('x', 'X', '*'):
            minor = None
        else:
            if not re.fullmatch(r'\d+', p1):
                raise ValueError(f"Invalid version part: {p1}")
            if len(p1) > 1 and p1[0] == '0':
                raise ValueError(f"Leading zero in version part: {p1}")
            minor = int(p1)
    elif len(parts) == 3:
        p0, p1, p2 = parts
        if p0 in ('x', 'X', '*'):
            major = None
        else:
            if not re.fullmatch(r'\d+', p0):
                raise ValueError(f"Invalid version part: {p0}")
            if len(p0) > 1 and p0[0] == '0':
                raise ValueError(f"Leading zero in version part: {p0}")
            major = int(p0)

        if p1 in ('x', 'X', '*'):
            minor = None
        else:
            if not re.fullmatch(r'\d+', p1):
                raise ValueError(f"Invalid version part: {p1}")
            if len(p1) > 1 and p1[0] == '0':
                raise ValueError(f"Leading zero in version part: {p1}")
            minor = int(p1)

        if p2 in ('x', 'X', '*'):
            patch = None
        else:
            if not re.fullmatch(r'\d+', p2):
                raise ValueError(f"Invalid version part: {p2}")
            if len(p2) > 1 and p2[0] == '0':
                raise ValueError(f"Leading zero in version part: {p2}")
            patch = int(p2)
    else:
        raise ValueError(f"Invalid partial version format: {core}")

    return major, minor, patch, prerelease


def _make_version(maj, min_, pat, pre=None):
    maj = 0 if maj is None else maj
    min_ = 0 if min_ is None else min_
    pat = 0 if pat is None else pat
    return Version(maj, min_, pat, pre)


def _expand_comparator(token: str) -> List[Tuple[str, Version]]:
    token = token.strip()
    if not token:
        raise ValueError("Empty comparator")

    op = '='
    rest = token

    if token.startswith('>='):
        op = '>='
        rest = token[2:]
    elif token.startswith('<='):
        op = '<='
        rest = token[2:]
    elif token.startswith('>'):
        op = '>'
        rest = token[1:]
    elif token.startswith('<'):
        op = '<'
        rest = token[1:]
    elif token.startswith('='):
        op = '='
        rest = token[1:]

    rest = rest.strip()
    if not rest:
        raise ValueError("Missing version in comparator")

    major, minor, patch, prerelease = _parse_partial_version_robust(rest)

    # Case 1: All parts None (X or *)
    if major is None and minor is None and patch is None:
        return [] # Matches anything

    # Case 2: Major only
    if major is not None and minor is None and patch is None:
        if op == '=':
            lower = _make_version(major, 0, 0)
            upper = _make_version(major + 1, 0, 0)
            return [('>=', lower), ('<', upper)]
        elif op == '>':
            lower = _make_version(major + 1, 0, 0)
            return [('>=', lower)]
        elif op == '<':
            upper = _make_version(major, 0, 0)
            return [('<', upper)]
        elif op == '<=':
            upper = _make_version(major + 1, 0, 0)
            return [('<', upper)]
        elif op == '>=':
            lower = _make_version(major, 0, 0)
            return [('>=', lower)]

    # Case 3: Major and Minor
    if major is not None and minor is not None and patch is None:
        if op == '=':
            lower = _make_version(major, minor, 0)
            upper = _make_version(major, minor + 1, 0)
            return [('>=', lower), ('<', upper)]
        elif op == '>':
            lower = _make_version(major, minor + 1, 0)
            return [('>=', lower)]
        elif op == '<':
            upper = _make_version(major, minor, 0)
            return [('<', upper)]
        elif op == '<=':
            upper = _make_version(major, minor + 1, 0)
            return [('<', upper)]
        elif op == '>=':
            lower = _make_version(major, minor, 0)
            return [('>=', lower)]

    # Case 4: Full version (Major, Minor, Patch)
    if major is not None and minor is not None and patch is not None:
        v = _make_version(major, minor, patch, prerelease)

        if op == '=':
            return [('>=', v), ('<=', v)]
        elif op == '>':
            return [('>', v)]
        elif op == '<':
            return [('<', v)]
        elif op == '<=':
            return [('<=', v)]
        elif op == '>=':
            return [('>=', v)]

    # Case 5: Major is None (e.g., *.1)
    if major is None:
        if minor is not None:
            lower = _make_version(0, minor, 0)
            return [('>=', lower)]
        elif patch is not None:
            lower = _make_version(0, 0, patch)
            return [('>=', lower)]

    raise ValueError(f"Could not expand comparator: {token}")


def _parse_tilde(token: str) -> List[Tuple[str, Version]]:
    token = token.strip()
    if not token.startswith('~'):
        raise ValueError("Not a tilde range")
    rest = token[1:].strip()

    major, minor, patch, prerelease = _parse_partial_version_robust(rest)

    if major is not None:
        if minor is not None:
            if patch is not None:
                lower = _make_version(major, minor, patch, prerelease)
                upper = _make_version(major, minor + 1, 0)
                return [('>=', lower), ('<', upper)]
            else:
                lower = _make_version(major, minor, 0)
                upper = _make_version(major, minor + 1, 0)
                return [('>=', lower), ('<', upper)]
        else:
            lower = _make_version(major, 0, 0)
            upper = _make_version(major + 1, 0, 0)
            return [('>=', lower), ('<', upper)]
    else:
        lower = _make_version(0, 0, 0)
        return [('>=', lower)]


def _parse_caret(token: str) -> List[Tuple[str, Version]]:
    token = token.strip()
    if not token.startswith('^'):
        raise ValueError("Not a caret range")
    rest = token[1:].strip()

    major, minor, patch, prerelease = _parse_partial_version_robust(rest)

    if major is None:
        lower = _make_version(0, 0, 0)
        return [('>=', lower)]

    if minor is None:
        if major == 0:
            lower = _make_version(0, 0, 0)
            upper = _make_version(1, 0, 0)
            return [('>=', lower), ('<', upper)]
        else:
            lower = _make_version(major, 0, 0)
            upper = _make_version(major + 1, 0, 0)
            return [('>=', lower), ('<', upper)]

    if patch is None:
        if major == 0:
            lower = _make_version(0, minor, 0)
            upper = _make_version(0, minor + 1, 0)
            return [('>=', lower), ('<', upper)]
        else:
            lower = _make_version(major, minor, 0)
            upper = _make_version(major + 1, 0, 0)
            return [('>=', lower), ('<', upper)]

    # Patch is present (numeric)
    lower = _make_version(major, minor, patch, prerelease)

    if major == 0:
        if minor == 0:
            upper = _make_version(0, 0, patch + 1)
        else:
            upper = _make_version(0, minor + 1, 0)
    else:
        upper = _make_version(major + 1, 0, 0)

    return [('>=', lower), ('<', upper)]


def _parse_hyphen(token: str) -> List[Tuple[str, Version]]:
    parts = token.split(' - ')
    if len(parts) != 2:
        raise ValueError(f"Invalid hyphen range: {token}")

    lower_str = parts[0].strip()
    upper_str = parts[1].strip()

    lower_major, lower_minor, lower_patch, _ = _parse_partial_version_robust(lower_str)
    upper_major, upper_minor, upper_patch, _ = _parse_partial_version_robust(upper_str)

    lower_v = _make_version(lower_major, lower_minor, lower_patch)

    if upper_major is not None and upper_minor is not None and upper_patch is not None:
        upper_v = _make_version(upper_major, upper_minor, upper_patch)
        op_upper = '<='
    else:
        if upper_patch is None:
            if upper_minor is not None:
                upper_v = _make_version(upper_major, upper_minor + 1, 0)
            else:
                upper_v = _make_version(upper_major + 1, 0, 0)
        else:
            # This case implies patch is present but minor/major might be None?
            # If patch is present, it's numeric.
            # If minor is None and major is None, e.g. x.x.3? 
            # Let's assume standard increment.
            upper_v = _make_version(upper_major, upper_minor, upper_patch + 1)

        op_upper = '<'

    return [('>=', lower_v), (op_upper, upper_v)]


def _parse_set(set_str: str) -> List[Tuple[str, Version]]:
    set_str = set_str.strip()
    if not set_str:
        return []

    if set_str == '*':
        return []

    if ' - ' in set_str:
        return _parse_hyphen(set_str)

    tokens = set_str.split()

    all_comps = []
    for token in tokens:
        if token.startswith('~'):
            comps = _parse_tilde(token)
        elif token.startswith('^'):
            comps = _parse_caret(token)
        else:
            comps = _expand_comparator(token)

        all_comps.extend(comps)

    return all_comps


def _check_set_matches(v: Version, comps: List[Tuple[str, Version]]) -> bool:
    if v.prerelease is not None:
        found = False
        for op, cv in comps:
            if cv.prerelease is not None:
                if (v.major == cv.major and v.minor == cv.minor and v.patch == cv.patch):
                    found = True
                    break
        if not found:
            return False

    for op, cv in comps:
        if op == '>=':
            if not (v >= cv):
                return False
        elif op == '<=':
            if not (v <= cv):
                return False
        elif op == '>':
            if not (v > cv):
                return False
        elif op == '<':
            if not (v < cv):
                return False
        elif op == '=':
            if v != cv:
                return False

    return True


def satisfies(version: str, rng: str) -> bool:
    v = parse(version)

    sets_str = rng.split('||')

    for set_str in sets_str:
        set_str = set_str.strip()
        if not set_str:
            continue

        comps = _parse_set(set_str)

        if _check_set_matches(v, comps):
            return True

    return False


def max_satisfying(versions: list[str], rng: str) -> Optional[str]:
    best = None
    best_version = None

    for v_str in versions:
        if satisfies(v_str, rng):
            v = parse(v_str)
            if best is None or v > best_version:
                best = v_str
                best_version = v

    return best
