import re


def split_command(line: str, env: dict[str, str]) -> list[str]:
    """
    Split a command line into words according to POSIX shell-like rules (subset).
    Supports single quotes, double quotes, backslash escapes, and parameter expansion.
    Does not use shlex.

    Args:
        line: The input string to split.
        env: Dictionary of environment variables for expansion.

    Returns:
        A list of words (strings).

    Raises:
        ValueError: For unterminated quotes, unterminated ${, or trailing unescaped backslash.
    """

    def expand(text: str) -> str:
        """
        Expand $NAME, ${NAME}, ${NAME:-default}, ${NAME-default} in text.
        The default text itself undergoes expansion.
        Returns the expanded string.
        """
        result = []
        i = 0
        n = len(text)

        while i < n:
            ch = text[i]

            if ch == '$':
                # Check what follows $
                if i + 1 >= n:
                    # Literal $ at end
                    result.append('$')
                    i += 1
                    continue

                next_ch = text[i + 1]

                if next_ch == '{':
                    # ${...} form
                    # Find the matching }
                    j = i + 2
                    depth = 1
                    while j < n and depth > 0:
                        if text[j] == '{':
                            depth += 1
                        elif text[j] == '}':
                            depth -= 1
                        j += 1

                    if depth != 0:
                        raise ValueError("Unterminated ${")

                    # content is text[i+2:j-1]
                    content = text[i + 2 : j - 1]

                    # Parse the content for NAME, default, and operator
                    # The format is: NAME, optionally followed by :-default or -default
                    k = 0
                    if k >= len(content):
                        raise ValueError("Invalid ${")

                    first_char = content[k]
                    if not (first_char.isalpha() or first_char == '_'):
                        raise ValueError("Invalid ${")

                    k += 1
                    while k < len(content) and (content[k].isalnum() or content[k] == '_'):
                        k += 1

                    name = content[:k]
                    rest = content[k:]

                    use_default_if_empty = False
                    has_default = False
                    default_text = ''

                    if rest.startswith(':-'):
                        has_default = True
                        use_default_if_empty = True
                        default_text = rest[2:]
                    elif rest.startswith('-') and len(rest) > 1:
                        has_default = True
                        use_default_if_empty = False
                        default_text = rest[1:]
                    elif len(rest) == 0:
                        pass
                    else:
                        raise ValueError("Invalid ${")

                    # Get the variable value
                    var_value = env.get(name, None)

                    if has_default:
                        if use_default_if_empty:
                            # Use default if unset OR empty
                            if var_value is None or var_value == '':
                                expanded_default = expand(default_text)
                                result.append(expanded_default)
                            else:
                                result.append(var_value)
                        else:
                            # Use default only if unset
                            if var_value is None:
                                expanded_default = expand(default_text)
                                result.append(expanded_default)
                            else:
                                result.append(var_value)
                    else:
                        # No default
                        if var_value is not None:
                            result.append(var_value)
                        # else: unset, append nothing (empty string)

                    i = j  # Move past the }
                    continue

                elif next_ch.isalpha() or next_ch == '_':
                    # $NAME form - longest match of [A-Za-z_][A-Za-z0-9_]*
                    k = i + 1
                    while k < n and (text[k].isalnum() or text[k] == '_'):
                        k += 1

                    name = text[i + 1 : k]
                    var_value = env.get(name, None)

                    if var_value is not None:
                        result.append(var_value)

                    i = k
                    continue

                else:
                    # $ followed by something else: literal $
                    result.append('$')
                    i += 1
                    continue

            else:
                result.append(ch)
                i += 1

        return ''.join(result)

    # Parse the line into tokens
    # Each token is either ('ws', None) or ('word_part', (text, is_quoted, is_unquoted_expansion))
    tokens = []
    i = 0
    n = len(line)

    while i < n:
        ch = line[i]

        if ch in (' ', '\t', '\n'):
            tokens.append(('ws', None))
            i += 1

        elif ch == "'":
            j = i + 1
            while j < n and line[j] != "'":
                j += 1
            if j >= n:
                raise ValueError("Unterminated single quote")

            quoted_text = line[i + 1 : j]
            tokens.append(('word_part', (quoted_text, True, False)))
            i = j + 1

        elif ch == '"':
            j = i + 1
            quoted_text_parts = []
            while j < n:
                if line[j] == '\\':
                    if j + 1 >= n:
                        raise ValueError("Trailing unescaped backslash")
                    next_ch = line[j + 1]
                    if next_ch in ('$', '"', '\\', '\n'):
                        if next_ch == '\n':
                            pass  # Backslash-newline removed entirely
                        else:
                            quoted_text_parts.append(next_ch)
                        j += 2
                    else:
                        # Any other backslash stays as is
                        quoted_text_parts.append('\\')
                        j += 1
                elif line[j] == '"':
                    break
                else:
                    quoted_text_parts.append(line[j])
                    j += 1

            if j >= n:
                raise ValueError("Unterminated double quote")

            quoted_text = ''.join(quoted_text_parts)
            # Expand $ in the quoted text
            expanded_text = expand(quoted_text)
            tokens.append(('word_part', (expanded_text, True, False)))
            i = j + 1

        elif ch == '\\':
            if i + 1 >= n:
                raise ValueError("Trailing unescaped backslash")
            next_ch = line[i + 1]
            if next_ch == '\n':
                # Backslash-newline removed entirely, no token
                pass
            else:
                tokens.append(('word_part', (next_ch, False, False)))
            i += 2

        elif ch == '$':
            if i + 1 >= n:
                tokens.append(('word_part', ('$', False, False)))
                i += 1
                continue

            next_ch = line[i + 1]

            if next_ch == '{':
                j = i + 2
                depth = 1
                while j < n and depth > 0:
                    if line[j] == '{':
                        depth += 1
                    elif line[j] == '}':
                        depth -= 1
                    j += 1

                if depth != 0:
                    raise ValueError("Unterminated ${")

                content = line[i + 2 : j - 1]

                k = 0
                if k >= len(content):
                    raise ValueError("Invalid ${")

                first_char = content[k]
                if not (first_char.isalpha() or first_char == '_'):
                    raise ValueError("Invalid ${")

                k += 1
                while k < len(content) and (content[k].isalnum() or content[k] == '_'):
                    k += 1

                name = content[:k]
                rest = content[k:]

                use_default_if_empty = False
                has_default = False
                default_text = ''

                if rest.startswith(':-'):
                    has_default = True
                    use_default_if_empty = True
                    default_text = rest[2:]
                elif rest.startswith('-') and len(rest) > 1:
                    has_default = True
                    use_default_if_empty = False
                    default_text = rest[1:]
                elif len(rest) == 0:
                    pass
                else:
                    raise ValueError("Invalid ${")

                var_value = env.get(name, None)

                if has_default:
                    if use_default_if_empty:
                        if var_value is None or var_value == '':
                            expanded_val = expand(default_text)
                        else:
                            expanded_val = var_value
                    else:
                        if var_value is None:
                            expanded_val = expand(default_text)
                        else:
                            expanded_val = var_value
                else:
                    if var_value is not None:
                        expanded_val = var_value
                    else:
                        expanded_val = ''

                tokens.append(('word_part', (expanded_val, False, True)))
                i = j

            elif next_ch.isalpha() or next_ch == '_':
                k = i + 1
                while k < n and (line[k].isalnum() or line[k] == '_'):
                    k += 1

                name = line[i + 1 : k]
                var_value = env.get(name, None)

                if var_value is not None:
                    expanded_val = var_value
                else:
                    expanded_val = ''

                tokens.append(('word_part', (expanded_val, False, True)))
                i = k

            else:
                # $ followed by something else: literal $
                tokens.append(('word_part', ('$', False, False)))
                i += 1

        else:
            tokens.append(('word_part', (ch, False, False)))
            i += 1

    # Group word_parts into words (separated by whitespace)
    result_words = []
    current_word_parts = []

    def flush_current_word():
        nonlocal current_word_parts
        if not current_word_parts:
            return

        full_text = ''.join(p[0] for p in current_word_parts)
        has_unquoted_expansion = any(p[2] for p in current_word_parts)
        has_quoted_or_literal = any(not p[2] for p in current_word_parts)

        if has_unquoted_expansion:
            # Split the full text on whitespace (spaces, tabs, newlines)
            pieces = re.split(r'[ \t\n]+', full_text)
            # Remove empty strings from splitting
            pieces = [p for p in pieces if p != '']

            if not pieces:
                # Entirely unquoted expansion(s) that became empty
                if has_unquoted_expansion and not has_quoted_or_literal:
                    pass  # Don't add - word is removed
                else:
                    result_words.append('')
            else:
                for piece in pieces:
                    result_words.append(piece)
        else:
            # No unquoted expansion, just add the word as is
            if full_text == '' and not has_quoted_or_literal:
                pass  # Shouldn't happen since no unquoted expansion
            else:
                result_words.append(full_text)

        current_word_parts = []

    for token in tokens:
        if token[0] == 'ws':
            flush_current_word()
        else:
            current_word_parts.append(token[1])

    # Flush the last word
    flush_current_word()

    return result_words
