from __future__ import annotations

import dataclasses
import typing
from typing import Any, get_type_hints


class LoadError(ValueError):
    def __init__(self, path: str, message: str):
        self.path = path
        super().__init__(f"{path}: {message}")

    def __str__(self) -> str:
        return f"{self.path}: {super().__str__()[len(self.path)+2:]}"


def _resolve_annotation(annotation: Any, cls: type) -> Any:
    """Resolve string annotations using get_type_hints."""
    if isinstance(annotation, str):
        # Use get_type_hints to resolve
        hints = get_type_hints(cls)
        # Find the field with this annotation? Actually we should just eval it in the module's namespace
        import sys
        mod = sys.modules.get(cls.__module__)
        ns = {}
        if mod:
            ns = vars(mod)
        try:
            return eval(annotation, ns)
        except Exception:
            raise LoadError("$", f"Cannot resolve annotation {annotation!r}")
    return annotation


def _load_value(value: Any, annotation: Any, path: str) -> Any:
    """Load a value according to the given annotation."""
    # Handle Optional / Union types
    origin = typing.get_origin(annotation)
    args = typing.get_args(annotation)

    # Check if it's Optional[T] (i.e., T | None)
    is_optional = False
    optional_inner = None
    if origin is typing.Union:
        none_type = type(None)
        non_none_args = [a for a in args if a is not none_type]
        if len(non_none_args) == 1 and len(args) == 2:
