            raise LoadError(path, f"expected dict, got {type(value).__name__}")
        val_type = args[1] if len(args) > 1 else Any
        result = {}
        for k, v in value.items():
            if not isinstance(k, str):
                raise LoadError(f"{path}.{k}", f"expected dict key to be str, got {type(k).__name__}")
            result[k] = _load_value(v, val_type, f"{path}.{k}")
        return result

    # Handle tuple[T, ...] (variable length) or tuple[A, B, C] (fixed length)
    if origin is tuple:
        if not isinstance(value, list):
            raise LoadError(path, f"expected tuple/list, got {type(value).__name__}")

        if len(args) == 2 and args[1] is Ellipsis:
