            return tuple(result)
        else:
            if len(value) != len(args):
                raise LoadError(path, f"expected tuple of length {len(args)}, got {len(value)}")
            result = []
            for i, (item, elem_type) in enumerate(zip(value, args)):
                result.append(_load_value(item, elem_type, f"{path}[{i}]"))
