    raise LoadError(path, f"unsupported annotation {annotation!r}")


def load(cls: type, data: Any, base_path: str = "$") -> Any:
    """Build an instance of dataclass cls from JSON-like data."""
    if not isinstance(data, dict):
        raise LoadError(base_path, f"expected dict for dataclass {cls.__name__}, got {type(data).__name__}")

    hints = get_type_hints(cls)
    fields = dataclasses.fields(cls)

    # Check for unknown keys
    field_names = {f.name for f in fields}
    for key in data:
        if key not in field_names:
            raise LoadError(f"{base_path}.{key}", f"unknown field {key!r}")

    kwargs = {}
    for field in fields:
        name = field.name
        annotation = hints.get(name, Any)
        field_path = f"{base_path}.{name}"

        if name in data:
            value = data[name]
            kwargs[name] = _load_value(value, annotation, field_path)
        else:
            # Missing key - use default or default_factory
            has_default = field.default is not dataclasses.MISSING
            has_default_factory = field.default_factory is not dataclasses.MISSING

            if has_default:
                kwargs[name] = field.default
            elif has_default_factory:
                kwargs[name] = field.default_factory()
            else:
                raise LoadError(field_path, f"missing required field {name!r}")

    return cls(**kwargs)
