function process_record(nf, fields,   i, idx, val) {
    if (!header_done) {
        for (i = 1; i <= nf; i++) {
            headers[i] = fields[i]
        }
        header_count = nf
        header_done = 1

        if (col_index > 0) {
            if (col_index > header_count) {
                print "Error: unknown column #" colindex > "/dev/stderr"
                exit 3
            }
            target_col = col_index
        } else {
            found = 0
            for (i = 1; i <= header_count; i++) {
                if (headers[i] == col_name) {
                    target_col = i
                    found = 1
                    break
                }
            }
            if (!found) {
                print "Error: unknown column " colname > "/dev/stderr"
                exit 3
            }
        }
        return
    }

    idx = target_col
    if (idx <= nf) {
        val = fields[idx]
    } else {
        val = ""
    }

    if (stats) {
        if (val ~ /^[+-]?([0-9]+(\.[0-9]*)?|\.[0-9]+)$/) {
            num = val + 0
            count++
            sum += num
            if (count == 1 || num < min_val) min_val = num
            if (count == 1 || num > max_val) max_val = num
        }
    } else {
        gsub(/\n/, "\\n", val)
        print val
    }
}
