{
    line = $0
    if (icase == 1) {
        line = tolower(line)
    }

    # Split into tokens by non-valid characters
    # Valid chars: letters, digits, apostrophes
    # We need to extract maximal runs of [a-zA-Z0-9\'] (or lowercase if icase)

    # Use a manual approach: iterate through the string character by character
    len = length(line)
    i = 1
    while (i <= len) {
        c = substr(line, i, 1)
        if (c ~ /[a-zA-Z0-9\']/) {
            # Start of a token
            start = i
            while (i <= len && substr(line, i, 1) ~ /[a-zA-Z0-9\']/) {
                i++
            }
            word = substr(line, start, i - start)

            # Strip leading and trailing apostrophes
