                word = substr(word, 2)
            }
            while (length(word) > 0 && substr(word, length(word), 1) == "\x27") {
                word = substr(word, 1, length(word) - 1)
            }

            # Ignore if only apostrophes (now empty) or empty
            if (length(word) > 0) {
                count[word]++
            }
        } else {
            i++
        }
    }
}
END {
    # Collect all words with their counts
    nwords = 0
    for (w in count) {
        nwords++
        words[nwords] = w
    }

    # Sort by count descending, then word ascending (byte order)
    # Simple bubble sort since we cannot rely on gawk extensions
